configfiles.configfile:
{ "system": "$technology", "data_folder": "./", "create_bellavista_inputs": true,
"visualization_parameters": { "plot_image": true, "plot_transcripts": true, "plot_cell_seg": true, "genes_visible_on_startup": false, #if $plot_all_genes.all_genes == "Yes" "plot_allgenes": true, #else "plot_allgenes": false, #set $gene_list = ['"' + str(x.strip()) + '"' for x in str($plot_all_genes.selected_genes).split(',')] #set $genes = ','.join($gene_list) "selected_genes": $genes, #end if "rotate_angle": $rotate_angle, "transcript_point_size": $transcript_point_size },
"input_files": { "images": "${images.element_identifier}.${images.ext}", "z_plane": $z_plane, #if $cell_segmentation: "cell_segmentation": "${cell_segmentation.element_identifier}.${cell_segmentation.ext}", #end if #if $nuclear_segmentation: "nuclear_segmentation": "${nuclear_segmentation.element_identifier}.${nuclear_segmentation.ext}", #end if #if $um_to_px_transform: "um_to_px_transform": "micron_to_mosaic_pixel_transform.csv", #end if "transcript_filename": "${transcript_filename.element_identifier}.${transcript_filename.ext}" } }
